import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"End-to-end suites","description":"","frontmatter":{},"headers":[],"relativePath":"dev/e2e-suites.md","filePath":"dev/e2e-suites.md"}'),d={name:"dev/e2e-suites.md"};function r(i,e,c,l,n,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="end-to-end-suites" tabindex="-1">End-to-end suites <a class="header-anchor" href="#end-to-end-suites" aria-label="Permalink to &quot;End-to-end suites&quot;">​</a></h1><p>The deep tests that gate a release. All of them drive a real QEMU boot through pexpect on the serial console; the matrix below is what the release evidence quotes (real outputs, skip counts declared). CI itself is build-only - these run sandbox/release-time (<code>tools/build_release.sh --deep</code>).</p><h2 id="_1-the-verification-matrix" tabindex="-1">1. The verification matrix <a class="header-anchor" href="#_1-the-verification-matrix" aria-label="Permalink to &quot;1. The verification matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Gate</th><th>Tool</th><th>The line it must print</th></tr></thead><tbody><tr><td>1</td><td>Host unit tests (<code>make test</code>)</td><td><code>tools/run_host_tests.py</code></td><td>all harnesses PASS (SKIP-FIXTURE declared)</td></tr><tr><td>2</td><td>Full regression 31/31</td><td><code>tools/run_fix4_regression.py</code></td><td><code>=== 31/31 checks passed</code></td></tr><tr><td>3</td><td>SSH E2E</td><td><code>tools/ssh_g11a_e2e.py</code></td><td><code>[g11a] ALL PASS</code> (5 checks)</td></tr><tr><td>4</td><td>HTTPS E2E</td><td><code>tools/run_fix4_https_e2e.py</code></td><td><code>=== 8/8 HTTPS E2E checks passed</code></td></tr><tr><td>5</td><td>Watchdog/logging/health</td><td><code>tools/wp12_watchdog_logging_e2e.py</code></td><td>S1-S14</td></tr><tr><td>6</td><td>TUI / Chinese / desktop</td><td><code>tools/wp10_*.py</code></td><td>per-suite</td></tr><tr><td>7</td><td>Mega-app smoke</td><td>the WP-l1apps-merge smoke script</td><td>21/21</td></tr></tbody></table><h2 id="_2-the-regression-gate-all-31-checks" tabindex="-1">2. The regression gate - all 31 checks <a class="header-anchor" href="#_2-the-regression-gate-all-31-checks" aria-label="Permalink to &quot;2. The regression gate - all 31 checks&quot;">​</a></h2><p><code>tools/run_fix4_regression.py</code> boots the ISO (512M, <code>-serial mon:stdio</code>, e1000 user-net, an HMP monitor unix socket for the framebuffer assertion), waits for <code>ush&gt;</code>, runs 24 commands, then checks. Each pattern is scoped to ONE command&#39;s output section (BUG #64 fix: whole-log matching was structurally always-true) and the echoed command line is stripped so name-bearing patterns can never be self-satisfied.</p><p><strong>Boot group (6)</strong></p><ol><li>screen framebuffer alive (BUG #66) - HMP screendump, &gt;= 2 colors + a measurable foreground ratio (serial-only gates once passed on a dead panel)</li><li>boot banner ready - <code>Open Cube OS User-space Shell \\(3\\.0\\.0</code></li><li>boot prompt hint - <code>Type &#39;help&#39; for built-in commands</code></li><li>boot complete OK - <code>boot complete\\.+ OK</code></li><li>exception self-test 3/3</li><li>command count &gt;= 276 - counted dynamically from the <code>help -a</code> registry rows (measured <strong>284</strong> on the WP-l1apps-merge tree); the interface-freeze floor</li></ol><p><strong>System group (2)</strong></p><ol start="7"><li>uname current tree - version regex incl. WP-10/11/12/13/14 markers</li><li>crashlog clean boot - <code>no exceptions recorded|0 entries|N entries</code></li></ol><p><strong>Self-test programs group (17)</strong></p><ol start="9"><li>heaptest pass - <code>\\bPASS\\b</code></li><li>fstest pass - <code>VFS self-test.*PASS</code></li><li>cryptotest NIST pass</li><li>l1test wp8b loader 14/14 - <code>ext_wp8b selftest 14/14 - PASS</code></li><li>l1test job steps PASS</li><li>l1test overall PASS</li><li>hello output</li><li>fork_test</li><li>exec_test</li><li>pipe_test</li><li>signal_test</li><li>select_test</li><li>mmap_test</li><li>mmap_multi</li><li>g7mmap (BUG-0281)</li><li>p3_test (priority)</li><li>g6_test full chain - async tally <code>failed tests = 0</code> (separate 300 s wait)</li></ol><p><strong>Dynamic-link group (5)</strong></p><ol start="26"><li>dyn_hello - <code>hello from dynamic program</code></li><li>so_test - <code>foo_add(2,3)=5</code></li><li>dlsym_test - <code>foo_add(7,8)=15</code></li><li>pie_test - <code>loaded at 0x...</code></li><li>reloc_test - <code>foo_add=30 foo_global=42 fp=300</code></li></ol><p><strong>Security group (1)</strong></p><ol start="31"><li>p0leak fence pass - <code>all kernel-address probes fenced</code></li></ol><p>Exit code = number of failed checks; the release matrix quotes 31/31.</p><h2 id="_3-the-ssh-e2e-5-5-tools-ssh-g11a-e2e-py" tabindex="-1">3. The SSH E2E (5/5) - tools/ssh_g11a_e2e.py <a class="header-anchor" href="#_3-the-ssh-e2e-5-5-tools-ssh-g11a-e2e-py" aria-label="Permalink to &quot;3. The SSH E2E (5/5) - tools/ssh_g11a_e2e.py&quot;">​</a></h2><p>Direction A (guest client -&gt; host <code>tools/paramiko_sshd.py</code> on :2222):</p><ol><li><code>ssh-auth</code> - <code>[ssh] authenticated (USERAUTH_SUCCESS)</code></li><li><code>ssh-exec</code> - <code>[ssh] exec output: hello-from-OpenCubeOS-kernel-ssh</code></li></ol><p>Direction B (guest <code>sshd 22 oc oc</code> &lt;- host paramiko client via hostfwd tcp::2223-:22):</p><ol start="3"><li><code>sshd-listen</code> - <code>listening on port 22</code></li><li><code>sshd-exec</code> - client <code>uname</code> returns <code>Open Cube OS</code></li><li><code>sshd-capture-log</code> - <code>exec: captured N bytes of output</code></li></ol><p>Operational notes baked into the tooling:</p><ul><li>TCG RSA-2048 keygen &gt; 500 s - pre-seed the host key (n||d, 256 B each, e=65537) into <code>build/etc.img</code> with <code>tools/host_keygen_etc.py</code>; the loader takes the &quot;key already on disk&quot; fast path (<code>OC_ETC_IMG</code> selects the pre-seeded image).</li><li>Generous paramiko timeouts (banner 420 s) - every TCG handshake stage takes tens of seconds.</li><li>Warm the ARP cache with one client-direction packet before the server test (cold-cache SYN-ACK stall).</li></ul><h2 id="_4-the-https-e2e-8-8-tools-run-fix4-https-e2e-py" tabindex="-1">4. The HTTPS E2E (8/8) - tools/run_fix4_https_e2e.py <a class="header-anchor" href="#_4-the-https-e2e-8-8-tools-run-fix4-https-e2e-py" aria-label="Permalink to &quot;4. The HTTPS E2E (8/8) - tools/run_fix4_https_e2e.py&quot;">​</a></h2><p>Against <code>tools/https_test_server.py</code> (one-request OpenSSL server matched to the kernel client: TLS 1.2 only, 0x0067 DHE-RSA-AES128-SHA256, 1024-bit RFC 3526 DH, self-signed; <code>observe</code> mode = raw-byte close_notify recorder; <code>eof</code> mode = hard-close truncation server):</p><ol start="0"><li><strong>self-signed chain REFUSED by default</strong> (BUG #21 acceptance) - <code>config set tls.insecure 1</code> is the explicit opt-in used for the compatibility pass</li><li>TLS handshake - kernel logs <code>Connecting ... (TLS)</code></li><li>TLS 1.2 + cipher DHE-RSA-AES128-SHA256 (0x0067) negotiated (server side)</li><li>encrypted <code>GET /hello.txt</code> received (server side)</li><li>canonical body served (<code>body=24</code>)</li><li>kernel saved the body (<code>wget</code> + <code>cat /wget_https.html</code> matches)</li><li>kernel close_notify observed (raw-byte recorder mode)</li><li><strong>truncation guard</strong> - the hard-close server (<code>eof</code> mode) makes the kernel fail promptly (&lt; 45 s, error text) instead of hanging</li></ol><p>Cert/DH fixtures are generated in-run: openssl self-signed RSA-2048 + DH params pinned to the RFC 3526 1024-bit MODP group (ASN.1-built from the server&#39;s own <code>P_HEX</code>).</p><h2 id="_5-the-mega-app-smoke-21-21" tabindex="-1">5. The mega-app smoke (21/21) <a class="header-anchor" href="#_5-the-mega-app-smoke-21-21" aria-label="Permalink to &quot;5. The mega-app smoke (21/21)&quot;">​</a></h2><p>Phase A - classic dispatch is byte-compatible: <code>disk-tool lsblk</code>, <code>net-tool ip</code>, <code>sound-tool sound</code>, <code>sysdiag health</code>, <code>hwinfo uname</code>, <code>power sleep 1</code>, <code>files df</code>, <code>update status</code>, <code>disk-tool direct lsblk</code>, and the unknown-op usage line.</p><p>Phase B - the wizards: every app&#39;s no-arg menu renders and quits on <code>q</code>; <code>disk-tool</code> runs lsblk through menu key 1 + the ENTER pause; <code>update</code> walks steps 1-2 for real (network check, A/B absence handling) and returns to ush cleanly.</p><p>Note: there is no committed <code>tools/test_megaapps.py</code> in the tree - the smoke rig is referenced as &quot;the WP-l1apps-merge smoke script&quot; (21/21 quoted in the release notes); a maintainer reproducing the matrix re-creates it from the Phase A/B checklists above.</p><h2 id="_6-host-unit-tests-tools-run-host-tests-py" tabindex="-1">6. Host unit tests - tools/run_host_tests.py <a class="header-anchor" href="#_6-host-unit-tests-tools-run-host-tests-py" aria-label="Permalink to &quot;6. Host unit tests - tools/run_host_tests.py&quot;">​</a></h2><p>The harnesses compile L0 components host-side and run them: multiboot2 parser (ASAN), crypto (NIST AES/SHA/HMAC, RSA, X.509, AEAD), TLS 1.3 key schedule vs RFC 8448, TCP congestion control (CUBIC), block-512 gate, and the subsystem batteries (BT, WiFi, camera, SCSI, IR, touchpad). SKIP-FIXTURE harnesses run for real when the openssl fixtures exist - the state is always declared. Full inventory: <a href="./host-tests.html">host-tests.md</a>.</p><h2 id="_7-watchdog-tui-chinese-suites" tabindex="-1">7. Watchdog / TUI / Chinese suites <a class="header-anchor" href="#_7-watchdog-tui-chinese-suites" aria-label="Permalink to &quot;7. Watchdog / TUI / Chinese suites&quot;">​</a></h2><p><code>tools/wp12_watchdog_logging_e2e.py</code> - 14 scenarios S1-S14: klog levels/switches, logcat filters, dmesg replay, logctl, persistence + rotation <code>.1</code> chains, the global filter, <strong>S12: the Intel TCO real reset + second boot</strong> (q35, <code>-no-reboot</code>, discover, arm, starve, assert the second boot), <strong>S13: ACPI WDAT</strong> (a synthetic-but-valid WDAT table injected with <code>tools/make_wdat_table.py</code> via <code>-acpitable</code> drives the real q35 TCO registers), policy kill, health JSON.</p><p><code>tools/wp10_*.py</code> - TUI/Chinese/desktop/ chipset / timer / wireless / camera families; the manual verifier re-runs FLAPPING checks as isolated fresh-QEMU scenarios (QEMU drops serial RX bytes after HMP screendumps - verified with an in-kernel RX trace; functional rounds therefore never take screenshots).</p><h2 id="_8-pexpect-mechanics-and-serial-echo-tolerance" tabindex="-1">8. pexpect mechanics and serial-echo tolerance <a class="header-anchor" href="#_8-pexpect-mechanics-and-serial-echo-tolerance" aria-label="Permalink to &quot;8. pexpect mechanics and serial-echo tolerance&quot;">​</a></h2><p>The shared patterns every suite inherits (<code>tools/qemu_runner.py</code>):</p><ul><li><code>pexpect.spawn(QEMU, [...], encoding=&quot;latin-1&quot;, codec_errors=&quot;replace&quot;)</code> - latin-1 so every byte survives; NULs stripped before regex.</li><li>Prompt regex <code>(?:ush&gt;|oc&gt;)\\s</code> (override <code>OC_PROMPT</code>); the v2 flow adapter <code>boot_to_recovery()</code> sends <code>exit</code> at <code>ush&gt;</code> to reach the <code>oc&gt;</code> recovery prompt.</li><li><code>strip_ansi()</code> removes CSI sequences before matching.</li><li><strong>Serial-echo tolerance</strong> - the &quot;ega]&quot; phenomenon: when the guest echoes the typed command, the echo can overlap the <em>output</em> of the same command and eat the leading <code>&quot;e&quot;</code> of a <code>[tag]</code> bracket, so <code>gen_api_docs.py</code> treats <code>[tag]</code> brackets as optional and the regression gate scopes every pattern to its own command section and strips the echo line first.</li><li>Keystrokes a serial link cannot carry (arrows/Home/End) go through the HMP monitor <code>sendkey</code>; pointer input via QMP <code>input-send-event</code> (HMP mouse_move is dead on <code>-display none</code> + QEMU 10); screendumps via HMP <code>screendump</code> on a unix monitor socket; raw serial via unix-socket chardevs when control bytes must arrive verbatim.</li><li>Known flake source: QEMU intermittently drops serial RX right after an HMP screendump -&gt; functional rounds never take screenshots; flapping checks re-run isolated (<code>wp10_native_manual.py</code>).</li></ul>',40)])])}const m=t(d,[["render",r]]);export{u as __pageData,m as default};
